# Trauma (NREMT AEMT test plan: 7% to 11%).
# Figures: NASEMSO National Model EMS Clinical Guidelines v3.0 (2022): General Trauma
# Management (SBP target 90, head injury above 110, pediatric 20 mL/kg), Extremity Trauma
# and External Hemorrhage, Burns (Rule of 10), Crush Injury, Spinal Care. Needle
# decompression is a paramedic skill and appears only as a wrong option.
ITEMS = [
    # ---------- Practice Test 1 ----------
    O(1, 2, "Wound packing", "Place the steps for packing a deep, bleeding wound high in the groin in order.",
      ["Expose and find the bleeding point", "Push gauze into the wound's depth", "Keep packing until it is full", "Hold firm pressure over the packing", "Wrap a pressure bandage over it"],
      "Packing works only when gauze reaches the bleeding vessel, so find the source, feed gauze deep, fill the wound, hold firm pressure and then bind it. A tourniquet cannot fit above a wound this high."),
    N(1, 3, "Burn fluids", "A 60 kg adult has burns over about 30 percent of the body and is not in shock. Using the Rule of 10, what is the starting fluid rate in mL per hour?",
      300,
      "The Rule of 10 multiplies the burned percentage, rounded to the nearest 10, by 10 for adults of 40 to 80 kg: 30 x 10 = 300 mL per hour. Add 100 mL per hour for each 10 kg over 80 kg."),
    S(1, 2, "Hemorrhagic shock", "A stab wound to the abdomen has left the radial pulse absent and SBP 80. How much fluid should you give?",
      ["Boluses to an SBP near 90", "Fluid wide open to SBP 140", "None until he is in surgery", "A single 2 L bolus right away"],
      "Trauma resuscitation aims for an SBP near 90 mm Hg, a palpable radial pulse or an alert patient, given as 500 mL boluses. Pushing higher dilutes clotting factors and can restart bleeding."),
    S(1, 2, "Head injury", "For an adult with a serious head injury, NASEMSO advises keeping the SBP above:",
      ["110 mm Hg", "70 mm Hg", "90 mm Hg", "100 mm Hg"],
      "Even one episode of low blood pressure worsens brain injury, so the target for a head-injured adult is above 110 mm Hg, higher than the 90 mm Hg used for other bleeding trauma."),
    S(1, 2, "Scalp bleeding", "A scalp wound is bleeding briskly over a spot where the skull feels soft. How should you control it?",
      ["Press around the edges", "Press hard on the center", "Pack gauze into the wound", "Leave it to clot alone"],
      "Pressure directly on a possible depressed skull fracture can push bone fragments inward, so press around the edges with a bulky dressing. Scalp wounds bleed heavily and do need control."),
    S(1, 3, "Open chest wound", "After you seal a chest stab wound, the patient becomes more short of breath and his BP falls. What should you do?",
      ["Lift the dressing to vent air", "Place a second dressing on top", "Decompress with a needle", "Lay him flat on that side"],
      "Rising distress after an occlusive dressing suggests air trapped under pressure. Briefly lifting a corner lets it escape; needle decompression is a paramedic skill, so call for ALS as you transport."),
    S(1, 2, "Pediatric extrication", "A toddler strapped in a harnessed car seat needs spinal motion restriction after a crash. How is he removed?",
      ["Still strapped in the car seat", "Lifted out onto a long board", "Carried out by a parent", "Pulled out by the arms"],
      "NASEMSO extricates infants and toddlers already in a harnessed car seat while still strapped in it; the seat keeps the spine aligned. Older children in boosters may climb out with a collar on."),
    # ---------- Practice Test 2 ----------
    M(2, 2, "Occlusive dressings", "Which wounds need an occlusive dressing? Select two.",
      ["Open wound to the chest", "Large cut over a neck vein", "Forearm laceration", "Abrasion on the knee", "Deep cut on the palm"],
      "Open chest wounds can let air into the chest, and open neck veins can draw in air that travels to the heart, so both are sealed. Limb wounds are dressed and pressed."),
    X(2, 2, "Spinal motion restriction", "For each patient, specify whether a cervical collar and spinal motion restriction are indicated.",
      ["Midline neck tenderness after a fall", "Alert, sober, no pain or deficit", "Smells of alcohol after a crash", "Stab wound to the side of the neck", "Tingling in both hands after a dive"],
      ["Indicated", "Not indicated"], [0, 1, 0, 1, 0],
      "Midline tenderness, intoxication and neurologic signs call for a collar. An alert, sober patient with no pain or deficit does not need one, and a penetrating neck wound should not be collared because it hides bleeding and airway swelling."),
    S(2, 2, "Amputation", "A finger is nearly cut off and hangs by a strip of skin. What should you do with it?",
      ["Keep it attached; splint it", "Cut the skin strip to free it", "Pack the finger in ice", "Pull it straight to test it"],
      "A partial amputation stays attached: the skin bridge may carry blood flow that keeps the finger alive. Dress it with gentle pressure and splint it as it lies, then transport."),
    S(2, 1, "Evisceration", "Bowel protrudes from a deep abdominal cut. What is the right care?",
      ["Moist sterile dressing", "Push the bowel back in", "Pack it with dry gauze", "Leave it open to the air"],
      "Cover the organs with moist sterile dressing and an occlusive layer to keep them moist and warm. Pushing them back adds contamination, and dry gauze sticks to the tissue."),
    S(2, 2, "Impaled object", "A rod is impaled in a patient's thigh and the airway is clear. What should you do with it?",
      ["Stabilize it where it is", "Pull it out to stop bleeding", "Cut it flush with the skin", "Twist it to check depth"],
      "An impaled object is stabilized in place with bulky dressings because it may be plugging the bleeding it caused. Removal is only for an object blocking the airway or chest compressions."),
    S(2, 3, "Anticoagulants", "An 82-year-old on a blood thinner fell from standing and hit her head. She seems fine. Why is she high risk?",
      ["Delayed bleeding in the skull", "Her neck is certainly fractured", "Blood thinners raise her BP", "Her glucose is likely low"],
      "Anticoagulants make delayed bleeding inside the skull more likely after even a low fall, so the 2022 field triage guideline flags these patients for trauma center care. A normal first exam does not rule it out."),
    S(2, 2, "Trauma in pregnancy", "A woman 30 weeks pregnant is strapped flat to a long board and becomes dizzy and pale. What helps?",
      ["Tilt the board to her left", "Raise the head end of the board", "Put her legs up on pillows", "Loosen her collar"],
      "Lying flat lets the uterus press on the vena cava and cut blood return to the heart. Tilting the whole board to the left, or displacing the uterus by hand, relieves it."),
    # ---------- Drill only ----------
    N(0, 3, "Burn fluids", "A 100 kg adult has burns over about 30 percent of the body and is not in shock. Using the Rule of 10, what is the starting fluid rate in mL per hour?",
      500,
      "30 x 10 = 300 mL per hour for the burns, then add 100 mL per hour for each 10 kg over 80 kg: 100 kg is 20 kg over, so 300 + 200 = 500 mL per hour."),
    S(0, 2, "Burn size", "In an adult, how much body surface does one whole arm plus the front of the torso cover?",
      ["27 percent", "18 percent", "36 percent", "45 percent"],
      "By the Rule of Nines one arm is 9 percent and the front of the torso is 18 percent, so together they are 27 percent. Only partial and full thickness burns count toward the total."),
    S(0, 2, "Crush injury", "A worker's leg has been pinned under a beam for 3 hours. What should happen before the beam is lifted?",
      ["IV saline running", "A tourniquet placed and left on", "Oral fluids by mouth", "Lactated Ringer's bolus"],
      "Releasing a crushed limb floods the blood with potassium and acid, so NASEMSO starts normal saline before release. Lactated Ringer's is avoided because it contains potassium."),
    S(0, 2, "Flail chest", "Which finding defines a flail chest segment?",
      ["It moves in as he breathes in", "It bulges out as he breathes in", "It cracks when pressed lightly", "It stays still while breathing"],
      "A flail segment is two or more ribs broken in two or more places, so it is sucked inward on inhalation, the opposite of the rest of the chest. Crepitus alone shows a fracture, not a flail."),
    S(0, 2, "Pediatric trauma fluids", "A 20 kg child with trauma has poor perfusion. What is the first fluid bolus?",
      ["20 mL/kg", "5 mL/kg", "10 mL/kg", "15 mL/kg"],
      "Children with signs of shock get 20 mL/kg of crystalloid, here 400 mL, then reassessment before any repeat. Smaller 10 mL/kg boluses are kept for children in cardiogenic shock."),
    S(0, 1, "Burn dressing", "Once the burning has stopped, how does NASEMSO advise covering a large burn?",
      ["Dry dressing or clean sheet", "Wet towels changed often", "Thick layer of burn gel", "Antibiotic ointment"],
      "Cover burns with a dry dressing or a clean sheet to limit contamination and heat loss, and leave blisters intact. Gels and ointments are avoided, and wet coverings over a large area chill the patient."),
]
